240c737f piv: Check return values
 src/libopensc/card-piv.c | 6 +++++-
 1 file changed, 5 insertions(+), 1 deletion(-)
commit 240c737f93ecfa83bf8110212a3da9b2fd4e3731
Author: Jakub Jelen <jjelen@redhat.com>
Date:   Tue Sep 12 11:42:07 2023 +0200

    piv: Check return values

    Thanks coverity

    CID 400264

diff --git a/src/libopensc/card-piv.c b/src/libopensc/card-piv.c
index 4af3e58b..19378bf5 100644
--- a/src/libopensc/card-piv.c
+++ b/src/libopensc/card-piv.c
@@ -2200,7 +2200,11 @@ static int piv_sm_open(struct sc_card *card)
        if (cs == NULL)
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);

-       sc_lock(card);
+       r = sc_lock(card);
+       if (r != SC_SUCCESS) {
+               sc_log(card->ctx, "sc_lock failed");
+               return r;
+       }

        /* use for several hash operations */
        if ((hash_ctx = EVP_MD_CTX_new()) == NULL) {
7236a9ae piv: Simplify handling of IDsh length
 src/libopensc/card-piv.c | 25 ++++++++++++-------------
 1 file changed, 12 insertions(+), 13 deletions(-)
commit 7236a9ae4ec4a1fe318939371e34d05acb45b089
Author: Jakub Jelen <jjelen@redhat.com>
Date:   Tue Sep 12 12:06:31 2023 +0200

    piv: Simplify handling of IDsh length

    This prevents coverity thinking the value can be different from 8.

    CID 400263

diff --git a/src/libopensc/card-piv.c b/src/libopensc/card-piv.c
index 19378bf5..2234f14e 100644
--- a/src/libopensc/card-piv.c
+++ b/src/libopensc/card-piv.c
@@ -206,7 +206,6 @@ enum {

                int o0len; /* first in otherinfo */
                u8 o0_char;
-               size_t IDshlen;
                size_t CBhlen;
                size_t T16Qehlen;
                size_t IDsicclen;
@@ -229,7 +228,7 @@ enum {
 static cipher_suite_t css[PIV_CSS_SIZE] = {
                {PIV_CS_CS2, 256, NID_X9_62_prime256v1, {{1, 2, 840, 10045, 3, 1, 7, -1}},
                PIV_CS_CS2, 65, 16, 32, 61,
-               4, 0x09, 8, 1, 16, 8, 16, 1,
+               4, 0x09, 1, 16, 8, 16, 1,
                4, 128/8, SHA256_DIGEST_LENGTH,
                (EVP_MD *(*)(void)) EVP_sha256,
                (const EVP_CIPHER *(*)(void)) EVP_aes_128_cbc,
@@ -239,7 +238,7 @@ static cipher_suite_t css[PIV_CSS_SIZE] = {

                {PIV_CS_CS7, 384, NID_secp384r1, {{1, 3, 132, 0, 34, -1}},
                PIV_CS_CS7, 97, 16, 48, 69,
-               4, 0x0D, 8, 1, 16, 8, 24, 1,
+               4, 0x0D, 1, 16, 8, 24, 1,
                4, 256/8, SHA384_DIGEST_LENGTH,
                (EVP_MD *(*)(void)) EVP_sha384,
                (const EVP_CIPHER *(*)(void)) EVP_aes_256_cbc,
@@ -2266,7 +2265,7 @@ static int piv_sm_open(struct sc_card *card)
                goto err;
        }

-       r = len2a = sc_asn1_put_tag(0x81, NULL, 1 + cs->IDshlen + Qehlen, NULL, 0, NULL);
+       r = len2a = sc_asn1_put_tag(0x81, NULL, 1 + sizeof(IDsh) + Qehlen, NULL, 0, NULL);
        if (r < 0)
                goto err;
        r = len2b = sc_asn1_put_tag(0x80, NULL, 0, NULL, 0, NULL);
@@ -2287,7 +2286,7 @@ static int piv_sm_open(struct sc_card *card)
        if (r != SC_SUCCESS)
                goto err;

-       r = sc_asn1_put_tag(0x81, NULL, 1 + cs->IDshlen + Qehlen, p, sbuflen - (p - sbuf), &p);
+       r = sc_asn1_put_tag(0x81, NULL, 1 + sizeof(IDsh) + Qehlen, p, sbuflen - (p - sbuf), &p);
        if (r != SC_SUCCESS)
                goto err;

@@ -2299,9 +2298,9 @@ static int piv_sm_open(struct sc_card *card)
 #else
        pid = (unsigned long) getpid(); /* use PID as our ID so different from other processes */
 #endif
-       memcpy(IDsh, &pid, MIN(sizeof(pid), cs->IDshlen));
-       memcpy(p, IDsh, cs->IDshlen);
-       p += cs->IDshlen;
+       memcpy(IDsh, &pid, MIN(sizeof(pid), sizeof(IDsh)));
+       memcpy(p, IDsh, sizeof(IDsh));
+       p += sizeof(IDsh);
        memcpy(p, Qeh, Qehlen);
        p += Qehlen;

@@ -2494,9 +2493,9 @@ static int piv_sm_open(struct sc_card *card)
        for (i = 0; i <  cs->o0len; i++)
                *p++ = cs->o0_char; /* 0x09 or 0x0d */

-       *p++ = cs->IDshlen;
-       memcpy(p, IDsh, cs->IDshlen);
-       p += cs->IDshlen;
+       *p++ = sizeof(IDsh);
+       memcpy(p, IDsh, sizeof(IDsh));
+       p += sizeof(IDsh);

        *p++ = cs->CBhlen;
        memcpy(p, &CBh, cs->CBhlen);
@@ -2588,8 +2587,8 @@ static int piv_sm_open(struct sc_card *card)
                p += 6;
                memcpy(p, IDsicc, cs->IDsicclen);
                p += cs->IDsicclen;
-               memcpy(p, IDsh, cs->IDshlen);
-               p += cs->IDshlen;
+               memcpy(p, IDsh, sizeof(IDsh));
+               p += sizeof(IDsh);

                memcpy(p, Qeh_OS, Qeh_OSlen);
                p += Qeh_OSlen;
